"use client"

import { useState } from "react";
import z from "zod"
import Modal from "../../components/ui/Modal/Modal";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";

const serviceCategorySchema = z.object({
    title: z.string(),
    sortOrder: z.string(),
    isActive: z.boolean()
})
type TserviceCategorySchema = z.infer<typeof serviceCategorySchema>;

export default function ServiceCategoriesPage() {
    const [isOpen, setIsOpen] = useState<boolean>(false);
    const { register, handleSubmit, formState: { errors }, reset } = useForm<TserviceCategorySchema>({
        resolver: zodResolver(serviceCategorySchema),
        defaultValues: {
            title: "",
            sortOrder: "0",
            isActive: true
        }
    })
    return<main>
        <h1>Управление категориями услуг</h1>
        <section>
            <button onClick={() => setIsOpen(true)}>Создать</button>
        </section>
        <Modal isOpen={isOpen} onClose={() => setIsOpen(false)}>
            <h3>Новая категория</h3>
            <form>
                <label htmlFor="title">Название: </label>
                <input type="text" {...register("title")} maxLength={30} />
                <label htmlFor="title">Сортировка: </label>
                <input type="number" {...register("sortOrder")} />
                <label htmlFor="title">Активный: </label>
                <select {...register("isActive")}>
                    <option value="true">Да</option>
                    <option value="false">Нет</option>
                </select>
                <button type="submit">Создать</button>
            </form>
            <button onClick={()=> setIsOpen(false)}>Закрыть</button>
        </Modal>
    </main>
}